 * @return: Number of occurrences found
 */
int countWordOccurrences(const std::string& filename, const std::string& targetWord) {
    std::ifstream file(filename);

    // Check if file opened successfully
    if (!file.is_open()) {
        std::cerr << "Error: Could not open file '" << filename << "'" << std::endl;
        return -1;
    }

    std::string line;
    int count = 0;

    // Read file line by line
    while (std::getline(file, line)) {
        // Convert to lowercase for case-insensitive search
        std::string lowerLine = line;
        std::transform(lowerLine.begin(), lowerLine.end(), lowerLine.begin(), ::tolower);

        // Convert target word to lowercase
        std::string lowerTarget = targetWord;
        std::transform(lowerTarget.begin(), lowerTarget.end(), lowerTarget.begin(), ::tolower);

        // Create a stream from the line to process words
        std::istringstream iss(lowerLine);
        std::string word;

        // Extract words from the line and count matches
        while (iss >> word) {
            // Remove punctuation from the word
            std::string cleanWord = "";
            for (char c : word) {
                if (std::isalnum(c)) {
                    cleanWord += std::tolower(c);
                }
            }

            // Compare with target word (case-insensitive)
            if (cleanWord == lowerTarget) {
                count++;
            }
        }
    }

    file.close();
    return count;
}

